module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Complemented outputs for the AND and OR gates
    wire q0_n, q1_n, q2_n;

    // Assign complemented outputs
    assign q0_n = ~q0;
    assign q1_n = ~q1;
    assign q2_n = ~q2;

    // D flip-flops with synchronous reset (initial value 0)
    always @(posedge clk) begin
        // Reset condition: initialize to 0
        // In simulation, 'initial' block sets reset values; in synthesis,
        // the reset is typically inferred from the initial values below.
        // Here we use non-blocking assignments on every clock edge,
        // and the initial block below ensures zero initial state.
        q0 <= q0;  // placeholder to make synthesis happy, actual logic below
        q1 <= q1;
        q2 <= q2;
    end

    // Latch the new values based on the combinational logic
    // The D inputs are derived from the current state and input x.
    // However, the specification states:
    // "Input x goes to three different two-input gates: an XOR, an AND, and a OR gate.
    //  Each of the three gates is connected to the input of a D flip-flop"
    //
    // This implies the D input of each flip-flop is the output of its respective
    // two-input gate. The second input of each gate is the flip-flop's own output
    // (or its complement). This creates a feedback loop.
    //
    // Let's define the D inputs:
    // D0 = XOR(x, q0)
    // D1 = AND(x, ~q1)
    // D2 = OR(x, ~q2)

    always @(posedge clk) begin
        q0 <= x ^ q0;       // XOR gate: inputs are x and q0
        q1 <= x & q1_n;     // AND gate: inputs are x and ~q1
        q2 <= x | q2_n;     // OR  gate: inputs are x and ~q2
    end

    // Three-input NOR gate whose inputs are the flip-flop outputs
    // Z = NOR(q0, q1, q2)
    assign z = ~(q0 | q1 | q2);

    // Initial block to set reset state (simulation only, synthesis tool
    // may ignore or map to global reset)
    initial begin
        q0 = 1'b0;
        q1 = 1'b0;
        q2 = 1'b0;
    end

endmodule

