module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    //----------------------------------------------------------------
    // Internal signals and state definition
    //----------------------------------------------------------------
    typedef enum logic [2:0] {
        STATE_A   = 3'b000,
        STATE_B   = 3'b001,
        STATE_C   = 3'b010,
        STATE_D   = 3'b011,
        STATE_E   = 3'b100   // g = 0 permanently
    } state_t;

    state_t state, next_state;

    // Registers for monitoring the x sequence (1, 0, 1)
    // shift_x[1] holds the value from two cycles ago
    // shift_x[0] holds the value from one cycle ago
    logic [1:0] shift_x;

    // Counter for monitoring y in state D (counts cycles y is 0)
    // 2-bit counter is sufficient: 00, 01, 10 (then reset or go to E)
    logic [1:0] cnt_y;

    //----------------------------------------------------------------
    // Output assignments (combinational)
    //----------------------------------------------------------------
    // f is 1 in states B, C, D. State A and E have f = 0.
    // g is 1 only in state D.
    assign f = (state == STATE_B) | (state == STATE_C) | (state == STATE_D);
    assign g = (state == STATE_D);

    //----------------------------------------------------------------
    // State register (positive edge triggered, synchronous active-low reset)
    //----------------------------------------------------------------
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state     <= STATE_A;
            shift_x   <= 2'b00;
            cnt_y     <= 2'b00;
        end else begin
            state     <= next_state;
            // Shift register updates: new MSB is old LSB, new LSB is current x
            shift_x   <= {shift_x[0], x};
            // Counter updates: if y is 1, reset counter to 0; else increment
            if (y == 1'b1) begin
                cnt_y <= 2'b00;
            end else begin
                cnt_y <= cnt_y + 1'b1;
            end
        end
    end

    //----------------------------------------------------------------
    // Next-state logic (combinational)
    //----------------------------------------------------------------
    always_comb begin
        next_state = state; // default: stay in current state

        case (state)
            STATE_A: begin
                // As long as reset is asserted, stay in A.
                // When reset is de-asserted, go to B after the next clock edge.
                // The state update in the always_ff block handles the transition
                // on the rising edge, so here we just ensure the default is A.
                if (resetn) begin
                    // Reset de-asserted: transition to B
                    next_state = STATE_B;
                end
            end

            STATE_B: begin
                // f is 1 for this cycle. Move to C.
                next_state = STATE_C;
            end

            STATE_C: begin
                // Monitor x for the sequence 1, 0, 1.
                // The sequence is detected when the shift register contains
                // the pattern: two cycles ago = 1, one cycle ago = 0, current = 1
                // i.e., {shift_x[1], shift_x[0], x} == 3'b101
                if ({shift_x[1], shift_x[0], x} == 3'b101) begin
                    next_state = STATE_D;
                end
                // else stay in STATE_C
            end

            STATE_D: begin
                // g is 1. Monitor y.
                // If y becomes 1, reset the counter and stay in D.
                // If y remains 0 for two consecutive cycles (cnt_y reaches 2'b10),
                // then transition to STATE_E (g = 0 permanently).
                if (y == 1'b1) begin
                    // y went high: maintain g=1
                    next_state = STATE_D;
                end else begin
                    // y still low
                    if (cnt_y == 2'b10) begin
                        // Counted two cycles of y=0: g goes to 0 permanently
                        next_state = STATE_E;
                    end else begin
                        // Still within the two-cycle window
                        next_state = STATE_D;
                    end
                end
            end

            STATE_E: begin
                // g = 0 permanently. Stay in E regardless of inputs.
                next_state = STATE_E;
            end

            default: next_state = STATE_A;
        endcase
    end

endmodule

