module TopModule (
    input  clk,
    input  reset,
    input  slowena,
    output q
);

    // q is a 4-bit output representing the counter value
    output [3:0] q;

    // Internal register to hold the counter value
    reg [3:0] count;

    // Synchronous reset and enable logic
    always @(posedge clk) begin
        if (reset)
            count <= 4'b0000;
        else if (slowena) begin
            // Increment on every positive edge when slowena is high
            // Natural overflow from 9 (4'b1001) to 0 (4'b0000) occurs here
            count <= count + 1'b1;
        end
        // If slowena is low, count retains its current value (hold state)
    end

    // Continuous assignment to output the counter value
    assign q = count;

endmodule

